(()=>{
 const modal=document.createElement('dialog');modal.className='modal order-modal';modal.innerHTML='<div class="modal-inner"><div class="modal-head"><h2>Kelola ulasan produk</h2><button type="button" class="close" aria-label="Tutup">×</button></div><div class="order-detail"></div></div>';document.body.append(modal);modal.querySelector('.close').onclick=()=>modal.close();const content=modal.querySelector('.order-detail');
 async function load(id){content.textContent='Memuat ulasan…';try{const data=await api(`/api/products/${id}/reviews?admin=1`);content.innerHTML=data.reviews.length?data.reviews.map(item=>`<div class="order-box"><strong>${escapeHtml(item.customerName)} · ${item.rating}/5</strong><p style="white-space:pre-wrap;overflow-wrap:anywhere">${escapeHtml(item.comment)}</p><small>${item.isHidden?'Disembunyikan':'Ditampilkan'} · Pembelian terverifikasi</small><button type="button" class="secondary" data-review="${item.id}" data-hidden="${item.isHidden}">${item.isHidden?'Tampilkan kembali':'Sembunyikan spam'}</button></div>`).join(''):'Belum ada ulasan.';content.querySelectorAll('[data-review]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await api(`/api/reviews/${button.dataset.review}`,{method:'PATCH',body:JSON.stringify({isHidden:button.dataset.hidden==='0'})});await load(id)}catch(error){toast(error.message);button.disabled=false}})}catch(error){content.textContent=error.message}}
 function addButtons(){document.querySelectorAll('#productRows .edit-product').forEach(edit=>{if(edit.parentElement.querySelector('.review-admin'))return;const button=document.createElement('button');button.type='button';button.className='icon-btn review-admin';button.textContent='Ulasan';button.style.marginLeft='8px';button.onclick=()=>{modal.showModal();load(Number(edit.dataset.id))};edit.after(button)})}new MutationObserver(addButtons).observe(document.querySelector('#productRows'),{childList:true});addButtons();
})();
